<script lang="ts">
  import Icon from '#lib/Icon.svelte';
  import { onMount, tick } from 'svelte';
  import { api } from '#lib/client.js';
  import { language, t } from '#lib/i18n.js';
  let messages = $state<any[]>([]); let body = $state(''); let error = $state(''); let busy = $state(false); let loading = $state(true); let nextCursor = $state<string | null>(null); let container = $state<HTMLDivElement>();
  async function load(older = false) { try { const result = await api(`/api/chat${older && nextCursor ? `?before=${encodeURIComponent(nextCursor)}` : ''}`); const nearBottom = !container || container.scrollHeight - container.scrollTop - container.clientHeight < 90; if (older) messages = [...result.messages, ...messages]; else { const map = new Map([...messages, ...result.messages].map((x) => [x.id, x])); messages = [...map.values()].sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()); } if (older || loading) nextCursor = result.nextCursor; loading = false; if (!older && nearBottom) { await tick(); container?.scrollTo({ top: container.scrollHeight, behavior: 'smooth' }); } } catch (e) { error = (e as Error).message; loading = false; } }
  onMount(() => { void load(); const timer = setInterval(() => { if (!document.hidden) void load(); }, 5000); return () => clearInterval(timer); });
  async function send(event: SubmitEvent) { event.preventDefault(); if (!body.trim()) return; busy = true; error = ''; try { await api('/api/chat', { method: 'POST', body: JSON.stringify({ body }) }); body = ''; await load(); await tick(); container?.scrollTo({ top: container.scrollHeight, behavior: 'smooth' }); } catch (e) { error = (e as Error).message; } finally { busy = false; } }
</script>
<svelte:head><title>{$t.chat} · Torrents Duck</title></svelte:head>
<h1 class="sr-only">{$t.chat}</h1>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}
<section class="panel chat-panel"><div class="chat-messages" bind:this={container} aria-label={$t.messages}>{#if nextCursor}<button class="quiet-button" onclick={() => load(true)}>{$t.previousMessages}</button>{/if}{#if loading}<div class="empty"><p>{$t.loadingPage}</p></div>{:else if !messages.length}<div class="empty"><p>{$t.chatEmpty}</p></div>{/if}{#each messages as message (message.id)}<article class="chat-entry"><span class="avatar">{(message.name || 'D').slice(0, 1).toUpperCase()}</span><div><strong>{message.name}</strong><time datetime={message.createdAt}>{new Date(message.createdAt).toLocaleString($language, { dateStyle: 'short', timeStyle: 'short' })}</time><p>{message.body}</p></div></article>{/each}</div><form class="chat-form" onsubmit={send}><textarea aria-label={$t.message} placeholder={$t.message} bind:value={body} maxlength={2000} rows="1" required></textarea><button class="primary" disabled={busy || !body.trim()} aria-label={$t.send}><span class="send-label">{$t.send}</span><Icon name="send" size={18} /></button></form></section>
